import csv
import json
import io
import logging
import os
import time
from typing import Any, Iterator

from .models import Record, BatchResult

logger = logging.getLogger(__name__)


class BaseWriter:
    def __init__(self, output_path: str, buffer_size: int = 100):
        self.output_path: str = output_path
        self.buffer_size: int = buffer_size
        self._buffer: list[Record | dict[str, Any]] = []
        self._total_written: int = 0

    def write_record(self, record: Record | dict[str, Any]) -> None:
        self._buffer.append(record)
        if len(self._buffer) >= self.buffer_size:
            self.flush()

    def write_batch(self, records: list[Record | dict[str, Any]]) -> None:
        for record in records:
            self.write_record(record)

    def flush(self) -> None:
        raise NotImplementedError

    def close(self) -> None:
        if self._buffer:
            self.flush()

    @property
    def total_written(self) -> int:
        return self._total_written

    def __enter__(self) -> "BaseWriter":
        return self

    def __exit__(self, exc_type: type, exc_val: Any, exc_tb: Any) -> bool:
        self.close()
        return False


